package main

import (
	"context"
	"fmt"
	"sync/atomic"
	"time"

	"github.com/ing-bank/golibs/pkg/kubemock"
	"github.com/ing-bank/golibs/pkg/store/backends/kubernetes"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/runtime/schema"
	ctrl "sigs.k8s.io/controller-runtime"
	"sigs.k8s.io/controller-runtime/pkg/client"
	"sigs.k8s.io/controller-runtime/pkg/controller"
)

// Database is a minimal custom resource. In a real project this type and its
// DeepCopy methods are generated by controller-gen.
type Database struct {
	metav1.TypeMeta   `json:",inline"`
	metav1.ObjectMeta `json:"metadata,omitempty"`

	Spec   DatabaseSpec   `json:"spec"`
	Status DatabaseStatus `json:"status"`
}

// DatabaseSpec is the desired state.
type DatabaseSpec struct {
	Version string `json:"version,omitempty"`
}

// DatabaseStatus is the observed state, written only by the controller.
type DatabaseStatus struct {
	Phase              string `json:"phase,omitempty"`
	ObservedGeneration int64  `json:"observedGeneration,omitempty"`
}

// DeepCopyObject implements runtime.Object.
func (in *Database) DeepCopyObject() runtime.Object {
	out := *in
	in.ObjectMeta.DeepCopyInto(&out.ObjectMeta)
	return &out
}

// DatabaseList is required: informers and List calls need the List type
// registered in the scheme.
type DatabaseList struct {
	metav1.TypeMeta `json:",inline"`
	metav1.ListMeta `json:"metadata,omitempty"`

	Items []Database `json:"items"`
}

// DeepCopyObject implements runtime.Object.
func (in *DatabaseList) DeepCopyObject() runtime.Object {
	out := *in
	in.ListMeta.DeepCopyInto(&out.ListMeta)
	out.Items = make([]Database, len(in.Items))
	for i := range in.Items {
		out.Items[i] = *in.Items[i].DeepCopyObject().(*Database)
	}
	return &out
}

var databaseGV = schema.GroupVersion{Group: "example.com", Version: "v1"}

// DatabaseReconciler marks a Database ready for the generation it has seen.
//
// It writes the status on every reconcile without comparing first. That does
// not loop: the first write emits an update event and one more reconcile, and
// that reconcile writes an identical status, which the API server (and
// kubemock) treat as a no-op with no new resourceVersion and no event.
type DatabaseReconciler struct {
	Client client.Client

	// Reconciles counts Reconcile calls so the example can detect a loop.
	Reconciles atomic.Int64
}

// Reconcile implements reconcile.Reconciler.
func (r *DatabaseReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
	r.Reconciles.Add(1)
	var db Database
	if err := r.Client.Get(ctx, req.NamespacedName, &db); err != nil {
		return ctrl.Result{}, client.IgnoreNotFound(err)
	}

	db.Status = DatabaseStatus{Phase: "Ready", ObservedGeneration: db.Generation}
	return ctrl.Result{}, r.Client.Status().Update(ctx, &db)
}

// Example_withManager wires a key/value store and a controller to the same
// in-memory cluster. This is the setup for testing an application that
// writes resources through the store while an operator reconciles them:
//
//  1. Register the custom resource and its List type in a scheme; the
//     controller's typed client needs them.
//  2. kubemock.NewFakeCluster creates the in-memory cluster.
//  3. The manager and the store (kubernetes.NewFakeForCluster) both run on it.
//  4. Store writes trigger reconciles, and the store reads the status back.
func Example_withManager() {
	scheme := runtime.NewScheme()
	scheme.AddKnownTypes(databaseGV, &Database{}, &DatabaseList{})
	metav1.AddToGroupVersion(scheme, databaseGV)
	cluster := kubemock.NewFakeCluster(scheme)

	mgr, err := kubemock.NewManagerForFakeCluster(nil, ctrl.Options{Scheme: scheme}, cluster)
	if err != nil {
		panic(err)
	}
	reconciler := &DatabaseReconciler{Client: mgr.GetClient()}
	err = ctrl.NewControllerManagedBy(mgr).
		For(&Database{}).
		WithOptions(controller.Options{SkipNameValidation: new(true)}). // only needed when built repeatedly in one process
		Complete(reconciler)
	if err != nil {
		panic(err)
	}

	cfg := kubernetes.Config{Namespace: "default", Group: "example.com", Version: "v1", Resource: "databases"}
	dbs := kubernetes.NewFakeForCluster[*Database](cfg, cluster)

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	go func() {
		if err := mgr.Start(ctx); err != nil {
			panic(err)
		}
	}()

	err = dbs.Create(ctx, "orders", &Database{
		APIVersion: databaseGV.String(), Kind: "Database",
		Spec: DatabaseSpec{Version: "16"},
	})
	if err != nil {
		panic(err)
	}
	db := waitForObservedGeneration(ctx, dbs, "orders", 1)
	fmt.Printf("version=%s phase=%s observedGeneration=%d\n", db.Spec.Version, db.Status.Phase, db.Status.ObservedGeneration)

	// Changing the spec bumps the generation, and the controller catches up.
	// Updates need the current resourceVersion, just like on a real cluster.
	db.Spec.Version = "17"
	if err := dbs.Update(ctx, "orders", db); err != nil {
		panic(err)
	}
	db = waitForObservedGeneration(ctx, dbs, "orders", 2)
	fmt.Printf("version=%s phase=%s observedGeneration=%d\n", db.Spec.Version, db.Status.Phase, db.Status.ObservedGeneration)

	// Once caught up, the controller must go quiet. A reconcile loop would keep
	// increasing both the reconcile count and the resourceVersion.
	fmt.Println("settled:", settled(ctx, dbs, "orders", reconciler))

	// Output:
	// version=16 phase=Ready observedGeneration=1
	// version=17 phase=Ready observedGeneration=2
	// settled: true
}

// settled reports whether neither the reconcile count nor the object's
// resourceVersion changes over a quiet period. The first window lets the final
// no-op reconcile finish; the second must then see no activity at all.
func settled(ctx context.Context, dbs *kubernetes.DynamicResource[*Database], key string, r *DatabaseReconciler) bool {
	snapshot := func() (int64, string) {
		db, err := dbs.Read(ctx, key)
		if err != nil {
			panic(err)
		}
		return r.Reconciles.Load(), db.ResourceVersion
	}
	const quiet = 200 * time.Millisecond
	time.Sleep(quiet)
	count, rv := snapshot()
	time.Sleep(quiet)
	count2, rv2 := snapshot()
	return count == count2 && rv == rv2
}

// waitForObservedGeneration polls because reconciles run in the manager's
// goroutines. In tests, prefer require.Eventually.
func waitForObservedGeneration(ctx context.Context, dbs *kubernetes.DynamicResource[*Database], key string, gen int64) *Database {
	for ctx.Err() == nil {
		if db, err := dbs.Read(ctx, key); err == nil && db.Status.ObservedGeneration == gen {
			return db
		}
		time.Sleep(10 * time.Millisecond)
	}
	panic("timed out waiting for reconcile")
}
